    e('naming').onchange=function(){e('template-fields').hidden=this.value!=='template';};e('classification').onchange=categoryChoices;e('categories').onchange=categoryChoices;e('custom-categories').oninput=categoryChoices;
    e('region-mode').onchange=organizeOptions;e('region-classification').onchange=organizeOptions;e('ffprobe-enabled').onchange=organizeOptions;
    e('region-groups').onchange=function(event){var n=event.target,i=Number(n.dataset.regionIndex),key=n.dataset.regionKey;if(!s.regionGroups[i]||!key)return;s.regionGroups[i][key]=key==='countries'?n.value.toUpperCase().split(/[\s,，]+/).filter(Boolean):n.value.trim();};e('region-groups').onclick=function(event){var b=event.target.closest('[data-region-remove]');if(b){s.regionGroups.splice(Number(b.dataset.regionRemove),1);renderRegionGroups();}};
    e('quality8-rules').onchange=function(event){var n=event.target,r=(s.qualityRules||[])[Number(n.dataset.qualityIndex)],key=n.dataset.qualityField;if(!r||!key)return;r[key]=key==='enabled'?n.checked:n.value.split('\n').map(function(v){return v.trim();}).filter(Boolean);};e('quality8-rules').onclick=function(event){var n=event.target.closest('[data-quality-move]');if(!n)return;var i=Number(n.dataset.qualityIndex),j=i+Number(n.dataset.qualityMove);if(j<0||j>=s.qualityRules.length)return;var r=s.qualityRules.splice(i,1)[0];s.qualityRules.splice(j,0,r);renderQualityRules();};
