    e('directory-list').onclick=function(event){var b=event.target.closest('[data-directory-index]'),p=directoryPicker;if(!b||!p||p.loading||p.saving)return;var item=p.items[Number(b.dataset.directoryIndex)];if(!item)return;p.trail.push({id:item.id,name:item.name});p.offset=0;readPickerDirectories(p);};
    e('account').onchange=function(){closeDirectoryPicker(true);s.epoch++;s.account=this.value;guard(cancelQR);authStatus();e('file-list').replaceChildren();e('share-list').replaceChildren();e('plan-list').replaceChildren();e('correction').replaceChildren();s.directory='0';s.offset=0;s.trail=[{id:'0',name:'根目录'}];s.source=s.target=s.transfer=s.unknown=s.preview=s.plan=null;s.dirReady=false;s.dirRevision=0;s.overrides={};paths();guard(loadDirectories);if(s.tab==='files')guard(files);};
