  async function loadDirectories(){var account=s.account,epoch=s.epoch;s.dirReady=false;s.source=s.target=s.transfer=s.unknown=null;paths();if(!account){paths();return;}var r=await apiCall('/accounts/'+account+'/directories');if(epoch!==s.epoch||account!==s.account)return;Object.assign(s,r.directories);s.dirRevision=r.revision;s.dirReady=true;paths();}
  async function load(){mount();closeDirectoryPicker(true);await guard(async function(){var r=await apiCall('/status');var old=s.account;s.accounts=r.accounts;s.devices=r.devices||[];if(s.devices.length){e('device').replaceChildren();s.devices.forEach(function(d){var option=document.createElement('option');option.value=d.id;option.textContent=d.name;e('device').append(option);});e('device').value='alipaymini';}e('account').replaceChildren();r.accounts.forEach(function(a){var o=document.createElement('option');o.value=a.id;o.textContent=a.name+' · 115';e('account').append(o);});s.account=r.accounts.some(function(a){return a.id===old;})?old:(r.accounts[0]||{}).id||'';e('account').value=s.account;authStatus();await loadDirectories();paths();show(s.tab);if(!s.account)msg('请扫码或手动填写 Cookie 登录 115。');});}
  function show(tab){msg('');s.tab=tab;tabs.forEach(function(t){e(t[0]).hidden=t[0]!==tab;});paths();e('tabs').querySelectorAll('button').forEach(function(b){b.classList.toggle('on',b.dataset.cwTab===tab);b.setAttribute('aria-current',b.dataset.cwTab===tab?'page':'false');});if(tab==='files')guard(files);if(tab==='playback')guard(loadSettings);if(tab==='strm')guard(assets);if(tab==='organize'){guard(rules);guard(loadNaming);}if(tab==='accounts')guard(loadAuthorization);if(tab==='jobs')guard(loadJobs);}
  async function cancelQR(){if(s.timer)clearTimeout(s.timer);var id=s.flow;s.flow='';e('qr').hidden=true;if(id){try{await apiCall('/qr/'+id,undefined,'DELETE');}catch(error){if(error.status!==410)throw error;}}}
  async function qr(){await cancelQR();var r=await apiCall('/qr',{device:e('device').value,mode:'cookie',account_id:e('replace-account').checked?s.account||null:null});s.flow=r.flow_id;e('qr').src='/api/cloud/qr/'+s.flow+'/image';e('qr').hidden=false;e('qr-status').textContent='请用 115 App 扫码并确认所选设备登录';poll();}
  function poll(){if(!s.flow)return;s.timer=setTimeout(async function(){var id=s.flow;try{var r=await apiCall('/qr/'+id+'/poll',{});if(id!==s.flow)return;if(r.phase==='connected'){s.flow='';s.epoch++;s.account=r.account_id;e('qr').hidden=true;e('qr-status').textContent='登录成功';await load();}else if(r.phase==='expired'){s.flow='';e('qr').hidden=true;e('qr-status').textContent='二维码已过期，请重新获取';}else{e('qr-status').textContent=r.phase==='scanned'?'已扫描，等待确认':r.message||'等待扫码';poll();}}catch(error){if(id===s.flow){e('qr-status').textContent=error.message;if(error.status===410||error.status===409){s.flow='';e('qr').hidden=true;}else poll();}}},4500);}
  async function files(){need();var epoch=s.epoch,request=++s.fileRequest;var r=await apiCall('/files?'+new URLSearchParams({account_id:s.account,cid:s.directory,offset:s.offset}));if(epoch!==s.epoch||request!==s.fileRequest)return;e('breadcrumb').textContent=s.trail.map(function(t){return t.name;}).join(' / ')+' · '+r.total+' 项';e('file-list').innerHTML=r.items.map(function(f){return '<p><button class="btn gray" data-folder="'+(f.is_dir?x(f.id):'')+'">'+x(f.name)+'</button> <span class="hint">'+(f.is_dir?'目录':(f.size/1073741824).toFixed(2)+' GB')+'</span></p>';}).join('');e('file-list').onclick=function(event){var b=event.target.closest('[data-folder]');if(b&&b.dataset.folder){s.directory=b.dataset.folder;s.offset=0;s.trail.push({id:s.directory,name:b.textContent});guard(files);}};}
  async function share(cid,offset){need();var epoch=s.epoch,request=++s.shareRequest;var r=await apiCall('/shares/preview',{account_id:s.account,link:e('share').value.trim(),password:e('password').value.trim(),cid:cid,offset:offset});if(epoch!==s.epoch||request!==s.shareRequest)return;s.preview=Object.assign(r,{cid:cid});e('share-list').innerHTML=r.items.map(function(f){return '<p><label><input type="checkbox" data-share="'+x(f.id)+'">'+x(f.name)+'</label>'+(f.is_dir?'<button class="btn gray" data-share-folder="'+x(f.id)+'">进入目录</button>':'')+'</p>';}).join('');e('share-list').onclick=function(event){var b=event.target.closest('[data-share-folder]');if(b)guard(function(){return share(b.dataset.shareFolder,0);});};msg('分享共 '+r.total+' 项，当前预览 '+r.items.length+' 项');}
  async function submit(r){show('jobs');msg('任务已加入队列。');if(r.job_id)await detail(r.job_id);}
  async function receive(){need();var epoch=s.epoch;if(!s.preview||!s.transfer)throw Error('请预览分享并在文件页选择转存目录');var ids=Array.from(e('share-list').querySelectorAll('[data-share]:checked')).map(function(i){return i.dataset.share;});if(!ids.length)throw Error('请先选中要转存的内容');var organize=e('auto-organize').checked;if(organize&&!s.target)throw Error('请先选择整理归档目录');if(!await showModalConfirm('将 '+ids.length+' 项转存到「'+s.transfer.name+'」'+(organize?'，并自动整理、生成 STRM。':'。'),{title:'确认转存'}))return;if(epoch!==s.epoch)throw Error('账号已变化，请重新预览');var r=await apiCall('/transfers',{preview_id:s.preview.preview_id,file_ids:ids,target_cid:s.transfer.id,organize_target:organize?s.target.id:null,generate:true,confirmed:true});s.preview=null;await submit(r);}
  async function plan(){need();var epoch=s.epoch,request=++s.planRequest;if(!s.source||!s.target)throw Error('请在文件页选择来源和归档目录');if(s.savedNaming!==JSON.stringify(namingPayload()))throw Error('请先保存命名与分类配置，再生成预览');msg('正在识别并生成整理预览…');var r=await apiCall('/plans',{account_id:s.account,source_cid:s.source.id,target_cid:s.target.id,unknown_cid:s.unknown?s.unknown.id:null,overrides:s.overrides});if(epoch!==s.epoch||request!==s.planRequest)return;s.plan=r.plan;e('plan-list').innerHTML=r.plan.items.map(function(i){return '<article class="panel"><b>'+x(i.source.name)+'</b><p>→ '+x(i.media.directory+'/'+i.media.name)+'</p><small>'+x(i.media.category_reason||'')+' · '+x(i.media.subcategory||i.media.region||'')+' · '+x(mediaInfoText(i.media))+' · 关联文件 '+i.followers.length+' 项</small></article>';}).join('')+r.plan.skipped.map(function(i){return '<p>'+x(i.name)+'：'+x(i.reason)+(i.action==='unknown'?' → 未识别目录 / '+x(i.target):'')+'</p>';}).join('');renderQualityPreview(r.plan.quality8||{});e('plan-list').innerHTML+=(r.plan.filtered||[]).map(function(i){return '<p class="hint">已过滤（保留原位）：'+x(i.name)+' · '+x(i.reason)+'</p>';}).join('');e('correction').replaceChildren();r.plan.items.map(function(i){return {file_id:i.source.id,name:i.source.name};}).concat(r.plan.skipped).forEach(function(i){var o=document.createElement('option');o.value=i.file_id;o.textContent=i.name;e('correction').append(o);});msg('可整理 '+r.plan.items.length+' 项，移入未识别 '+(r.plan.unknown_items||[]).length+' 项，待修正 '+r.plan.skipped.filter(function(i){return i.action!=='unknown';}).length+' 项，已过滤 '+(r.plan.filtered||[]).length+' 项。');}
  async function apply(){var current=s.plan;if(!s.plan)throw Error('请先识别并预览');if(s.savedNaming!==JSON.stringify(namingPayload()))throw Error('命名与分类尚未保存，请保存并重新预览');if(!await showModalConfirm('按预览在 115 中改名和归档 '+s.plan.items.length+' 项'+((s.plan.unknown_items||[]).length?'，另将 '+s.plan.unknown_items.length+' 项保留原名移入未识别目录':'')+'。同名冲突会保留并提示。',{title:'执行整理'}))return;if(current!==s.plan)throw Error('选择已变化，请重新预览');var r=await apiCall('/plans/apply',{plan_id:s.plan.id,confirmed:true,generate:e('generate').checked});s.plan=null;await submit(r);}
